{
  "name": "range-expand",
  "version": "1.0.0",
  "description": "Expand ranges like '1-10' or 'a-z' into an array of values",
  "type": "module",
  "main": "src/index.js",
  "bin": {
    "range-expand": "src/cli.js"
  },
  "scripts": {
    "test": "node --test"
  },
  "keywords": [
    "range",
    "expand"
  ],
  "license": "MIT"
}

const NUMERIC_RANGE = /^(-?\d+)-(-?\d+)$/;
const ALPHA_RANGE = /^([a-zA-Z])-([a-zA-Z])$/;

function buildNumeric(start, end, step) {
  const direction = start <= end ? 1 : -1;
  const stride = Math.abs(step) * direction;
  const out = [];
  if (direction === 1) {
    for (let i = start; i <= end; i += stride) out.push(i);
  } else {
    for (let i = start; i >= end; i += stride) out.push(i);
  }
  return out;
}

function buildAlpha(start, end, step) {
  const a = start.codePointAt(0);
  const b = end.codePointAt(0);
  return buildNumeric(a, b, step).map((code) => String.fromCodePoint(code));
}

function expandToken(token, step) {
  const trimmed = token.trim();
  if (trimmed === "") throw new Error("Empty range token");

  const numMatch = trimmed.match(NUMERIC_RANGE);
  if (numMatch) {
    return buildNumeric(Number(numMatch[1]), Number(numMatch[2]), step);
  }

  const alphaMatch = trimmed.match(ALPHA_RANGE);
  if (alphaMatch) {
    return buildAlpha(alphaMatch[1], alphaMatch[2], step);
  }

  throw new Error(`Invalid range: "${token}"`);
}

export function expandRange(input, options = {}) {
  if (typeof input !== "string") {
    throw new TypeError("Range must be a string");
  }

  const { step = 1, maxSize = 10000 } = options;
  if (!Number.isInteger(step) || step === 0) {
    throw new RangeError("step must be a non-zero integer");
  }

  const values = input
    .split(",")
    .flatMap((token) => expandToken(token, step));

  if (values.length > maxSize) {
    throw new RangeError(`Range expands to ${values.length} values (max ${maxSize})`);
  }

  return values;
}

export default expandRange;

#!/usr/bin/env node
import { expandRange } from "./index.js";

const [, , range, ...rest] = process.argv;
const step = rest.length > 0 ? Number(rest[0]) : 1;

if (!range) {
  console.error("Usage: range-expand <range> [step]");
  console.error("Examples: range-expand 1-10 | range-expand a-z | range-expand 10-1 | range-expand 1-9,20-25");
  process.exit(1);
}

try {
  console.log(expandRange(range, { step }).join(" "));
} catch (err) {
  console.error(`Error: ${err.message}`);
  process.exit(1);
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { expandRange } from "../src/index.js";

test("expands an ascending numeric range", () => {
  assert.deepEqual(expandRange("1-5"), [1, 2, 3, 4, 5]);
});

test("expands a descending numeric range", () => {
  assert.deepEqual(expandRange("5-1"), [5, 4, 3, 2, 1]);
});

test("expands a single-character alpha range", () => {
  assert.deepEqual(expandRange("a-e"), ["a", "b", "c", "d", "e"]);
});

test("expands a descending alpha range", () => {
  assert.deepEqual(expandRange("e-a"), ["e", "d", "c", "b", "a"]);
});

test("supports negative numbers", () => {
  assert.deepEqual(expandRange("-2-2"), [-2, -1, 0, 1, 2]);
});

test("supports multiple comma-separated ranges", () => {
  assert.deepEqual(expandRange("1-3,7-9"), [1, 2, 3, 7, 8, 9]);
});

test("honors a custom step", () => {
  assert.deepEqual(expandRange("0-10", { step: 5 }), [0, 5, 10]);
});

test("rejects invalid input", () => {
  assert.throws(() => expandRange("abc"), /Invalid range/);
  assert.throws(() => expandRange("1..5"), /Invalid range/);
});

test("enforces max size", () => {
  assert.throws(() => expandRange("1-100", { maxSize: 10 }), /max/);
});
